def find_kth_sequence(n, k):
    def count_sequences(length, mod):
        if length == 0:
            return 1
        count = 0
        for petals in range(1, n):
            if (mod + petals) % n != 0:
                count += count_sequences(length - 1, (mod + petals) % n)
        return count

    def generate_sequence(length, mod, k):
        if length == 0:
            return []
        for petals in range(1, n):
            if (mod + petals) % n != 0:
                count = count_sequences(length - 1, (mod + petals) % n)
                if k <= count:
                    return [petals] + generate_sequence(length - 1, (mod + petals) % n, k)
                k -= count

    return generate_sequence(n - 1, 0, k)

