def generate_sequence(n, k):
    def is_valid(seq):
        prefix_sums = [0]
        for num in seq:
            prefix_sums.append((prefix_sums[-1] + num) % n)
        seen = set()
        for ps in prefix_sums[1:]:
            if ps in seen:
                return False
            seen.add(ps)
        return True

    def backtrack(seq, k):
        if len(seq) == n - 1:
            if is_valid(seq):
                return seq
            else:
                return None
        for i in range(1, n):
            seq.append(i)
            result = backtrack(seq, k)
            if result:
                return result
            seq.pop()
        return None

    return backtrack([], k)

